// internal/proxy/insert.go line 45-90
func (s *insertService) Insert(ctx context.Context, req *InsertRequest) (*InsertResponse, error) {
    data := req.GetData()

    // NO SIZE VALIDATION HERE - missing check for len(data) > 100
    // TODO: Add max insert size validation per REST v2 constraint

    // Proceed directly to segment writer
    result, err := s.segmentWriter.Insert(ctx, data)
    if err != nil {
        return nil, status.Errorf(codes.Internal, "insert failed: %v", err)
    }

    resp := &InsertResponse{
        InsertCount: int64(len(result.IDs)),
        InsertIds:  result.IDs,
    }
    return resp, nil
}
